import json
import re
import sys
from datetime import datetime, timezone

SRC = r"C:\Users\<usuario>\.claude\projects\C--OUTROS-PROJETOS---CLAUDE-namastex-fde-challenge\c9a6fac5-67b6-4dfd-afec-155e6c0c687b.jsonl"
OUT = r"C:\Users\<usuario>\AppData\Local\Temp\claude\C--OUTROS-PROJETOS---CLAUDE-namastex-fde-challenge\c9a6fac5-67b6-4dfd-afec-155e6c0c687b\scratchpad\sessao_pos_1524.md"

CUTOFF = datetime(2026, 9, 13, 18, 24, 0, tzinfo=timezone.utc)

SK_RE = re.compile(r"sk-[A-Za-z0-9_\-]{20,}")

def mask(text):
    if not isinstance(text, str):
        return text
    return SK_RE.sub("sk-[omitido]", text)

def parse_ts(ts):
    if not ts:
        return None
    try:
        # handle trailing Z
        if ts.endswith("Z"):
            ts = ts[:-1] + "+00:00"
        return datetime.fromisoformat(ts)
    except Exception:
        return None

def extract_text(content):
    """content can be a string or a list of blocks. Return text or None."""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for item in content:
            if not isinstance(item, dict):
                continue
            if item.get("type") == "text":
                t = item.get("text")
                if t:
                    parts.append(t)
        if parts:
            return "\n".join(parts)
        return None
    return None

def is_tool_result_only(content):
    """True if content is a list whose blocks are all tool_result (no text)."""
    if isinstance(content, list):
        has_text = any(isinstance(i, dict) and i.get("type") == "text" for i in content)
        has_tool_result = any(isinstance(i, dict) and i.get("type") == "tool_result" for i in content)
        if has_tool_result and not has_text:
            return True
    return False

count_lines = 0
count_written = 0
count_skipped_before = 0
count_cross_session = 0

with open(SRC, "r", encoding="utf-8", errors="replace") as fin, \
     open(OUT, "w", encoding="utf-8") as fout:
    for line in fin:
        count_lines += 1
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue

        ts_raw = obj.get("timestamp")
        ts = parse_ts(ts_raw)
        if ts is None:
            continue
        if ts < CUTOFF:
            count_skipped_before += 1
            continue

        mtype = obj.get("type")
        message = obj.get("message", {})
        if not isinstance(message, dict):
            continue
        content = message.get("content")

        if mtype == "user":
            # skip pure tool_result blocks
            if is_tool_result_only(content):
                continue
            text = extract_text(content)
            if text is None:
                continue
            stripped = text.lstrip()
            if stripped.startswith("<system-reminder>"):
                continue
            if stripped.startswith("<task-notification>"):
                continue
            if stripped.startswith("<cross-session-message"):
                # try to find from= attribute
                m = re.search(r'from[-_]?name="([^"]*)"', stripped)
                if not m:
                    m = re.search(r'from="([^"]*)"', stripped)
                fromname = m.group(1) if m else "desconhecido"
                fout.write(f"### {ts_raw} user\n[mensagem de outro chat: {fromname}]\n\n")
                count_cross_session += 1
                count_written += 1
                continue
            text = mask(text)
            fout.write(f"### {ts_raw} user\n{text}\n\n")
            count_written += 1

        elif mtype == "assistant":
            text = extract_text(content)
            if text is None:
                continue
            text = mask(text)
            fout.write(f"### {ts_raw} assistant\n{text}\n\n")
            count_written += 1

print(f"linhas lidas: {count_lines}")
print(f"antes do cutoff (ignoradas): {count_skipped_before}")
print(f"blocos escritos: {count_written}")
print(f"cross-session comprimidas: {count_cross_session}")
